// hooks/index.ts — the plugin entry point: registers every hook and starts
// the ticket loop when a session begins.

import type { Register } from 'claude-code'
import * as agent from './agent'
import * as policy from './policy'
import * as heartbeat from './heartbeat'
import * as animation from './animation'
import * as workflow from './workflow'
import * as approval from './approval'
import * as dashboard from './dashboard/render'
import type { Host } from './host'

// A repeat session.start (reconnect, hot reload) must drop the previous
// subscription, or every state change triggers one extra redraw per reload.
let unsubscribeWorkflow: (() => void) | undefined

export const register: Register = (on) => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await $.ui.open({ id: dashboard.PANE_ID, title: dashboard.PANE_TITLE })

    // Built inline so every member is a literal `$.noun.method(...)` call;
    // the object itself is plain data and can be passed anywhere (see host.ts).
    const host: Host = {
      now: () => $.clock.now(),
      sleep: (ms) => $.clock.sleep(ms),
      every: (ms, fn) => $.clock.every(ms, fn),
      storeGet: (key) => $.store.get(key),
      storeSet: (key, value) => $.store.set(key, value),
      storeDelete: (key) => $.store.delete(key),
      run: (argv, init) => $.process.run(argv, init),
      fsExists: (path) => $.fs.exists(path),
      spawnAgent: (args) => $.agent.spawn(args),
      listAgents: () => $.agent.list(),
      uiAsk: (question, options) => $.ui.ask(question, options),
      uiOpen: (args) => $.ui.open(args),
      uiInvalidate: (what) => $.ui.invalidate(what),
      uiLog: (text, opts) => $.ui.log(text, opts),
    }

    // Registered before the workflow starts, so no spawn can race it. Errors
    // are left to surface here rather than as unknown-subagent spawn denials.
    await $.agent.register({
      name: 'coding',
      description: 'autonomous-loop: implements a ticket in the current worktree (internal use only)',
      prompt:
        'You are an autonomous coding agent. Implement the given ticket in the current worktree ' +
        'using the available tools.',
      disallowedTools: policy.CODING_DENIED_TOOLS,
    })
    await $.agent.register({
      name: 'review',
      description: 'autonomous-loop: reviews the diff in the current worktree (internal use only)',
      prompt:
        'You are an autonomous code reviewer. Inspect the diff and evidence in the current ' +
        'worktree, then respond with PASS or FAIL.',
      tools: policy.REVIEW_ALLOWED_TOOLS,
    })

    // A pane the plugin opens on its own waits undrawn below 144 terminal
    // columns; one opened from a command the person typed is placed at any width.
    await $.command.register({
      name: 'autonomous-loop',
      description: 'Open the autonomous-loop dashboard',
    })

    heartbeat.startHeartbeat(host, {
      // Every active ticket needs its lease renewed, not just one.
      ticketIds: () => workflow.currentStates().map((s) => s.ticketId),
      onBeat: () => $.ui.invalidate('ui.render'),
    })
    animation.startAnimationTicker(
      host,
      // One shared animation for the pane: on while ANY ticket is coding/reviewing.
      () => workflow.currentStates().some((s) => s.status === 'coding' || s.status === 'reviewing'),
      () => $.ui.invalidate('ui.render'),
    )
    unsubscribeWorkflow?.()
    unsubscribeWorkflow = workflow.subscribe(() => $.ui.invalidate('ui.render'))
    void workflow.runWorkflow(host, { cwd: e.cwd }).catch((err) =>
      $.ui.log(`autonomous-loop: ${String(err)}`, { to: 'debug' }))
    return result
  })

  on('session.end', async ($, e, next) => {
    // Stop this process's timers and counters. Worktrees and leases are left
    // alone on purpose: an unfinished ticket resumes from them next session.
    heartbeat.stopHeartbeat()
    animation.stopAnimationTicker()
    policy.resetStats()
    return next(e)
  })

  // Every hook is written as a function literal at its on() call site: the
  // engine scans the source before loading and refuses a hook passed as a
  // factory's return value. Factories are called inside the literal instead.

  // The two agent types are for this plugin's own spawns only; hide them
  // from the main model's agent list.
  on('agent.offer', { agent: policy.CODING_AGENT_TYPE }, () => ({ isOffered: false }))
  on('agent.offer', { agent: policy.REVIEW_AGENT_TYPE }, () => ({ isOffered: false }))

  on('turn.complete', ($, e, next) => agent.createTurnCompleteHook()(e, next))
  // turn.step and tool.call are skipped for events the plugin's own agents
  // raise (the engine does not re-enter a plugin), so these only observe
  // other activity. Tool limits are enforced by agent.register above.
  on('turn.step', async function* ($, e, next) {
    return yield* agent.createTurnStepHook()(e, next)
  })
  on('tool.call', ($, e, next) =>
    policy.createToolCallHook({
      agentKindOf: agent.agentKindOf,
      observe: agent.observeToolCall,
    })(e, next),
  )
  // Opened from a command, so the pane is placed at any width. Re-opening an
  // already-open pane is a no-op. This hook is the command, so no next().
  on('command.run', { command: 'autonomous-loop' }, async ($) => {
    await $.ui.open({ id: dashboard.PANE_ID, title: dashboard.PANE_TITLE })
    return { text: 'Dashboard opened.' }
  })

  on('ui.render', { component: 'Pane' }, ($, e, next) => {
    if (!dashboard.isOwnPane(e)) return next(e)
    // Resolved here and passed down as elements — `$` itself never leaves this hook.
    const elements = $.ui.resolve(e)
    return dashboard.renderDashboard(elements, e, {
      states: workflow.currentStates(),
      emit: (ev) => workflow.submitEvent(ev),
      awaitingApproval: (ticketId) => approval.isAwaitingApproval(ticketId),
      awaitingHuman: (ticketId) => approval.isAwaitingHuman(ticketId),
    })
  })
}

