// hooks/agent.ts — spawns the coding and review subagents, tracks each by
// agentId, and resolves its run from the matching turn.complete. Exports hook
// factories only; index.ts does all the on(...) registration.

import type {
  EngineInterface,
  Frozen,
  Hook,
  Timer,
  ToolCallInput,
  TurnCompleteInput,
  TurnCompleteReason,
} from 'claude-code'
import type { Host } from './host'
import { pickModel } from './state'
import type { ModelTier, WorkflowState } from './state'
import { CODING_AGENT_TYPE, REVIEW_AGENT_TYPE } from './policy'

export type AgentKind = 'coding' | 'review'

export type AgentProgress = {
  agentId: string
  kind: AgentKind
  model: ModelTier
  steps: number
  toolCalls: readonly string[]
  lastText: string
  startedAtMs: number
}

export type AgentRunResult = {
  kind: AgentKind
  model: ModelTier
  agentId?: string
  answer: string
  isAborted: boolean
  reason?: TurnCompleteReason
  steps: number
  toolCalls: readonly string[]
  durationMs: number
  denied?: string
}

export type SpawnRequest = {
  kind: AgentKind
  state: WorkflowState
  prompt: string
  description: string
  cwd?: string
  subagentType?: string
}

// Registered by index.ts with policy.ts's tool lists (see policy.ts).
export const CODING_SUBAGENT_TYPE = CODING_AGENT_TYPE
export const REVIEW_SUBAGENT_TYPE = REVIEW_AGENT_TYPE

// ---------------------------------------------------------------------------
// Internal tracking state.
// ---------------------------------------------------------------------------

type PendingRun = {
  agentId: string
  kind: AgentKind
  model: ModelTier
  ticketId: string
  resolve: (result: AgentRunResult) => void
}

const progress = new Map<string, AgentProgress>()
const pending = new Map<string, PendingRun>()
const liveness = new Map<string, Timer>()

// An agent that dies without finishing a turn never sends turn.complete, so
// runAgent polls $.agent.list() to avoid waiting forever.
const LIVENESS_POLL_MS = 15_000

function stopLivenessWatch(agentId: string): void {
  liveness.get(agentId)?.cancel()
  liveness.delete(agentId)
}

/**
 * Settles the pending run as aborted if the engine reports the agent stopped
 * running before any turn.complete. The agent must be seen `running` once
 * first, so a listing that lags a fresh spawn is not mistaken for a death.
 */
function startLivenessWatch(host: Host, agentId: string): void {
  let sawRunning = false
  const timer = host.every(LIVENESS_POLL_MS, () => {
    void (async () => {
      const run = pending.get(agentId)
      if (run === undefined) {
        stopLivenessWatch(agentId)
        return
      }
      const infos = await host.listAgents()
      const info = infos.find((i) => i.id === agentId)
      if (info === undefined) {
        if (sawRunning) {
          settleDead(agentId, 'agent is no longer listed by $.agent.list() and no turn.complete arrived')
        }
        return
      }
      if (info.status === 'running') {
        sawRunning = true
        return
      }
      settleDead(
        agentId,
        `agent ended with status '${info.status}' and no turn.complete arrived`,
      )
    })()
  })
  liveness.set(agentId, timer)
}

/** Settles a run the engine reports as no longer running, absent a turn.complete. */
function settleDead(agentId: string, reason: string): void {
  const run = pending.get(agentId)
  if (run === undefined) return
  stopLivenessWatch(agentId)
  const p = progress.get(agentId)
  run.resolve({
    kind: run.kind,
    model: run.model,
    agentId,
    answer: '',
    isAborted: true,
    reason: 'aborted',
    steps: p?.steps ?? 0,
    toolCalls: p?.toolCalls ?? [],
    durationMs: 0,
    denied: reason,
  })
}

// ---------------------------------------------------------------------------
// Spawning.
// ---------------------------------------------------------------------------

export async function runAgent(
  host: Host,
  request: SpawnRequest,
): Promise<AgentRunResult> {
  // Route by `kind`, not by state.status, so a review always gets the review model.
  const model: ModelTier = pickModel({
    status: request.kind === 'review' ? 'reviewing' : 'coding',
    attempt: request.state.attempt,
  })

  const startedAtMs = await host.now()

  const spawned = await host.spawnAgent({
    prompt: request.prompt,
    description: request.description,
    subagentType:
      request.subagentType ??
      (request.kind === 'review' ? REVIEW_SUBAGENT_TYPE : CODING_SUBAGENT_TYPE),
    model,
    cwd: request.cwd ?? request.state.worktreePath,
  })

  if (spawned.deny !== undefined) {
    return {
      kind: request.kind,
      model,
      answer: '',
      isAborted: false,
      steps: 0,
      toolCalls: [],
      durationMs: 0,
      denied: spawned.deny,
    }
  }

  const agentId = spawned.agentId
  if (agentId === undefined) {
    return {
      kind: request.kind,
      model,
      answer: '',
      isAborted: false,
      steps: 0,
      toolCalls: [],
      durationMs: 0,
      denied: 'spawn resolved without an agentId',
    }
  }

  // Track before awaiting, so an early turn.complete is not missed.
  progress.set(agentId, {
    agentId,
    kind: request.kind,
    model,
    steps: 0,
    toolCalls: [],
    lastText: '',
    startedAtMs,
  })

  const result = await new Promise<AgentRunResult>((resolve) => {
    pending.set(agentId, {
      agentId,
      kind: request.kind,
      model,
      ticketId: request.state.ticketId,
      resolve: (result) => {
        pending.delete(agentId)
        progress.delete(agentId)
        stopLivenessWatch(agentId)
        resolve(result)
      },
    })
    startLivenessWatch(host, agentId)
  })
  return result
}

// ---------------------------------------------------------------------------
// Hook factories.
// ---------------------------------------------------------------------------

/**
 * Only `reason === 'answer'` is a real completion. Every other reason becomes
 * a `denied` string, so workflow.ts routes it to a blocker, not a finish.
 */
function deniedReasonFor(e: Frozen<TurnCompleteInput>): string | undefined {
  switch (e.reason) {
    case 'answer':
      return undefined
    case 'refusal':
      // Either field may be null.
      return `model refused: ${e.refusal.category ?? 'unknown'}${
        e.refusal.explanation ? ` — ${e.refusal.explanation}` : ''
      }`
    case 'aborted':
      return 'turn aborted (interrupted)'
    case 'error':
      return 'turn ended in error (retries exhausted or context limit)'
  }
}

// Hook bodies take no `$`: the loader refuses any function that receives `$`
// from outside its own on(...) call site.
type TurnCompleteHookBody = (
  e: Parameters<Hook<'turn.complete'>>[1],
  next: Parameters<Hook<'turn.complete'>>[2],
) => ReturnType<Hook<'turn.complete'>>

/** on('turn.complete', ...): resolves the deferred for e.agentId, then `return next(e)`. */
export function createTurnCompleteHook(): TurnCompleteHookBody {
  return (e, next) => {
    if (e.agentId !== undefined) {
      const run = pending.get(e.agentId)
      if (run !== undefined) {
        const p = progress.get(e.agentId)
        run.resolve({
          kind: run.kind,
          model: run.model,
          agentId: e.agentId,
          answer: e.answer,
          isAborted: e.isAborted,
          reason: e.reason,
          steps: p?.steps ?? 0,
          toolCalls: p?.toolCalls ?? [],
          durationMs: e.durationMs,
          denied: deniedReasonFor(e),
        })
      }
    }
    return next(e)
  }
}

type TurnStepHookBody = (
  e: Parameters<Hook<'turn.step'>>[1],
  next: Parameters<Hook<'turn.step'>>[2],
) => ReturnType<Hook<'turn.step'>>

/** on('turn.step', ...): async generator; `return yield* next(e)` after counting the step for e.agentId. */
export function createTurnStepHook(): TurnStepHookBody {
  return async function* (e, next) {
    const result = yield* next(e)
    if (e.agentId !== undefined) {
      const p = progress.get(e.agentId)
      if (p !== undefined) {
        p.steps += 1
        if (result?.answer) p.lastText = result.answer
      }
    }
    return result
  }
}

/** Called by policy.ts's tool.call hook (agent.ts registers no tool.call hook of its own). */
export function observeToolCall(e: Frozen<ToolCallInput>): void {
  if (e.agentId === undefined) return
  const p = progress.get(e.agentId)
  if (p === undefined) return
  p.toolCalls = [...p.toolCalls, e.tool]
}

// ---------------------------------------------------------------------------
// Read-only accessors.
// ---------------------------------------------------------------------------

export function agentKindOf(agentId: string | undefined): AgentKind | undefined {
  if (agentId === undefined) return undefined
  return progress.get(agentId)?.kind
}

export function isTrackedAgent(agentId: string | undefined): boolean {
  return agentId !== undefined && progress.has(agentId)
}

export function trackedAgents(): readonly AgentProgress[] {
  return [...progress.values()]
}

export function progressOf(agentId: string): AgentProgress | undefined {
  return progress.get(agentId)
}

// ---------------------------------------------------------------------------
// Teardown.
// ---------------------------------------------------------------------------

function settleAbandoned(run: PendingRun, reason: string): void {
  stopLivenessWatch(run.agentId)
  run.resolve({
    kind: run.kind,
    model: run.model,
    agentId: run.agentId,
    answer: '',
    isAborted: true,
    reason: 'aborted',
    steps: progress.get(run.agentId)?.steps ?? 0,
    toolCalls: progress.get(run.agentId)?.toolCalls ?? [],
    durationMs: 0,
    denied: reason,
  })
  pending.delete(run.agentId)
  progress.delete(run.agentId)
}

/** Aborts the agents of one ticket (on its Stop), never another ticket's. */
export function abandonForTicket(ticketId: string, reason: string): void {
  for (const run of [...pending.values()]) {
    if (run.ticketId === ticketId) settleAbandoned(run, reason)
  }
}

/** Aborts every pending agent, on full teardown. */
export function abandonAll(reason: string): void {
  for (const run of [...pending.values()]) settleAbandoned(run, reason)
}

/** Convenience over $.agent.list(), filtered to this plugin's tracked ids. */
export async function liveAgentStatuses(
  host: Host,
): Promise<Record<string, string>> {
  const infos = await host.listAgents()
  const ids = new Set(progress.keys())
  return Object.fromEntries(
    infos.filter((i) => ids.has(i.id)).map((i) => [i.id, i.status]),
  )
}

