// hooks/policy.ts — tool permissions for the loop's coding and review agents.

import type { Frozen, Hook, ToolCallInput } from 'claude-code'
import type { AgentKind } from './agent'

export type PolicyDecision =
  | { allow: true; reason?: undefined }
  | { allow: false; reason: string }

export type PolicyStats = {
  calls: number
  denied: number
  byTool: Record<string, number>
  deniedByTool: Record<string, number>
}

export type PolicyDeps = {
  agentKindOf: (agentId: string | undefined) => AgentKind | undefined
  observe: (e: Frozen<ToolCallInput>) => void
}

/** Tools a 'coding' subagent may never call. */
export const CODING_DENIED_TOOLS: readonly string[] = ['WebFetch', 'WebSearch', 'AskUserQuestion']

/** Tools a 'review' subagent may call; anything else is denied for kind === 'review'. */
export const REVIEW_ALLOWED_TOOLS: readonly string[] = ['Read', 'Grep', 'Glob', 'Bash']

// The real enforcement is at registration: index.ts registers these agent
// types with the lists above, and the engine applies them itself. A tool.call
// hook cannot do it -- tool.call and turn.step never fire for agents this
// plugin spawned. createToolCallHook below still polices every other caller.
export const PLUGIN_NAME = 'autonomous-loop'
export const CODING_AGENT_TYPE = `${PLUGIN_NAME}:coding`
export const REVIEW_AGENT_TYPE = `${PLUGIN_NAME}:review`

function emptyStats(): PolicyStats {
  return { calls: 0, denied: 0, byTool: {}, deniedByTool: {} }
}

let current: PolicyStats = emptyStats()

/** Pure: no $, no I/O. Calls outside a tracked agent (agentKind undefined) always allow. */
export function decide(args: {
  tool: string
  agentKind: AgentKind | undefined
}): PolicyDecision {
  const { tool, agentKind } = args
  if (agentKind === undefined) return { allow: true }
  if (agentKind === 'coding' && CODING_DENIED_TOOLS.includes(tool)) {
    return { allow: false, reason: `coding agents may not call ${tool}` }
  }
  if (agentKind === 'review' && !REVIEW_ALLOWED_TOOLS.includes(tool)) {
    return {
      allow: false,
      reason: `review agents may only use: ${REVIEW_ALLOWED_TOOLS.join(', ')}`,
    }
  }
  return { allow: true }
}

type ToolCallHookBody = (
  e: Parameters<Hook<'tool.call'>>[1],
  next: Parameters<Hook<'tool.call'>>[2],
) => ReturnType<Hook<'tool.call'>>

/** on('tool.call', ...): deps.observe(e), then `{ deny }` or `return next(e)`. */
export function createToolCallHook(deps: PolicyDeps): ToolCallHookBody {
  return (e, next) => {
    deps.observe(e)

    current.calls += 1
    current.byTool[e.tool] = (current.byTool[e.tool] ?? 0) + 1

    const decision = decide({ tool: e.tool, agentKind: deps.agentKindOf(e.agentId) })
    if (!decision.allow) {
      current.denied += 1
      current.deniedByTool[e.tool] = (current.deniedByTool[e.tool] ?? 0) + 1
      return { deny: decision.reason }
    }
    return next(e)
  }
}

export function stats(): PolicyStats {
  return {
    calls: current.calls,
    denied: current.denied,
    byTool: { ...current.byTool },
    deniedByTool: { ...current.deniedByTool },
  }
}

export function resetStats(): void {
  current = emptyStats()
}

