// hooks/heartbeat.ts — renews the lease on every actively worked ticket.

import type { Timer } from 'claude-code'

import type { Host } from './host'
import { getTicket, renewLease } from './ticket'

export type HeartbeatHandle = {
  cancel: () => void
}

export type HeartbeatOptions = {
  intervalMs?: number
  leaseMs?: number
  /** Every ticket currently being worked, read fresh at each tick. */
  ticketIds?: () => readonly string[]
  onBeat?: (nowMs: number) => void
}

export const DEFAULT_HEARTBEAT_INTERVAL_MS = 30_000
export const DEFAULT_LEASE_MS = 120_000

// Heartbeat's own key, written by nothing else, so it has no writer to race.
const HEARTBEAT_STORE_KEY = 'autonomous-loop/heartbeat'

let timer: Timer | undefined
let beats = 0
let lastBeat: number | undefined

async function beat(
  host: Host,
  options: HeartbeatOptions,
  leaseMs: number,
): Promise<void> {
  const nowMs = await host.now()
  const ticketIds = options.ticketIds?.() ?? []

  for (const ticketId of ticketIds) {
    // Re-check just before renewing: a ticket already done/blocked must never
    // have its lease extended.
    const ticket = await getTicket(host, ticketId).catch(() => undefined)
    if (ticket && ticket.status !== 'done' && ticket.status !== 'blocked') {
      await renewLease(host, ticketId, leaseMs).catch(() => undefined)
    }
  }

  // Never written through saveRuns: $.store has no compare-and-set, so
  // sharing workflow.ts's runs key would race its persist() writes.
  if (ticketIds.length > 0) {
    await host.storeSet(HEARTBEAT_STORE_KEY, {
      ticketIds,
      leaseExpiresAtMs: nowMs + leaseMs,
    })
  }

  beats += 1
  lastBeat = nowMs
  options.onBeat?.(nowMs)
}

export function startHeartbeat(
  host: Host,
  options: HeartbeatOptions = {},
): HeartbeatHandle {
  if (timer) {
    timer.cancel()
    timer = undefined
  }

  const intervalMs = options.intervalMs ?? DEFAULT_HEARTBEAT_INTERVAL_MS
  const leaseMs = options.leaseMs ?? DEFAULT_LEASE_MS

  timer = host.every(intervalMs, () => {
    void beat(host, options, leaseMs)
  })

  return { cancel: () => stopHeartbeat() }
}

export function stopHeartbeat(): void {
  timer?.cancel()
  timer = undefined
}

/** Full teardown, including the beat counters (for test isolation). */
export function reset(): void {
  stopHeartbeat()
  beats = 0
  lastBeat = undefined
}

export function isBeating(): boolean {
  return timer !== undefined
}

export function lastBeatMs(): number | undefined {
  return lastBeat
}

export function beatCount(): number {
  return beats
}

export function currentTimer(): Timer | undefined {
  return timer
}

