// hooks/animation.ts — the dashboard's LOOP banner: the word in a block font,
// with a row of blocks underneath that rolls as a wave while any agent works.
// Purely cosmetic UI state, kept out of the persisted WorkflowState.

import type { Timer } from 'claude-code'
import type { Host } from './host'

/** 6 letter rows + 1 block row underneath. */
export type Frame = readonly string[]

const BANNER: readonly string[] = [
  '██╗      ██████╗  ██████╗ ██████╗ ',
  '██║     ██╔═══██╗██╔═══██╗██╔══██╗',
  '██║     ██║   ██║██║   ██║██████╔╝',
  '██║     ██║   ██║██║   ██║██╔═══╝ ',
  '███████╗╚██████╔╝╚██████╔╝██║     ',
  '╚══════╝ ╚═════╝  ╚═════╝ ╚═╝     ',
]
/** Display width of every banner row, in cells. */
export const BANNER_WIDTH = [...BANNER[0]!].length
/** Block heights, lowest to highest. */
const LEVELS = '▁▂▃▄▅▆▇█'
/** Columns per wave crest; the frame cycle length too, so the wave rolls seamlessly. */
const WAVE_PERIOD = 12
const TICK_MS = 120

let timer: Timer | undefined
let frameIndex = 0
let wasWorking = false

function waveRow(tick: number): string {
  let row = ''
  for (let col = 0; col < BANNER_WIDTH; col++) {
    const phase = ((col - tick) / WAVE_PERIOD) * 2 * Math.PI
    const level = Math.round(((Math.sin(phase) + 1) / 2) * (LEVELS.length - 1))
    row += LEVELS[level]
  }
  return row
}

const IDLE_FRAME: Frame = [...BANNER, LEVELS[0]!.repeat(BANNER_WIDTH)]

/** The current frame to draw; a flat block row whenever nothing is actively running. */
export function currentFrame(): Frame {
  return wasWorking ? [...BANNER, waveRow(frameIndex)] : IDLE_FRAME
}

/**
 * Starts the banner's ticker (a repeat call is a no-op). Each tick reads
 * `isWorking()` fresh instead of reacting to transitions, so a session that
 * resumes mid-'coding' still animates. While idle a tick does nothing.
 */
export function startAnimationTicker(
  host: Host,
  isWorking: () => boolean,
  invalidate: () => void,
): void {
  if (timer !== undefined) return
  timer = host.every(TICK_MS, () => {
    const working = isWorking()
    if (!working) {
      if (wasWorking) invalidate() // one final redraw back to the still word
      wasWorking = false
      frameIndex = 0
      return
    }
    wasWorking = true
    frameIndex = (frameIndex + 1) % WAVE_PERIOD
    invalidate()
  })
}

export function stopAnimationTicker(): void {
  timer?.cancel()
  timer = undefined
  frameIndex = 0
  wasWorking = false
}

