// hooks/workflow.ts -- the loop itself: drives each ticket through the
// transition table, and runs up to `maxConcurrent` tickets at once.

import type { Host } from './host'
import {
  createInitialState,
  isTerminal,
  nextStatus,
  loadRuns,
  saveRuns,
  type WorkflowEvent,
  type WorkflowState,
} from './state'
import { getTicket, claimTicket, updateTicket, type Ticket } from './ticket'
import { repoRoot, prepareWorktree, worktreeExists, diffStat } from './worktree'
import { evaluateAttempt, type EvalReport } from './eval'
import { classifyFailure, toWorkflowEvent } from './blocker'
import {
  requestApproval,
  askHuman,
  resolveHumanAnswer,
  resolveApproval,
  cancelForTicket,
} from './approval'
import { runAgent, abandonForTicket } from './agent'

export type ExternalEvent =
  | { kind: 'HUMAN_ANSWERED'; ticketId: string; answer: string }
  | { kind: 'APPROVED'; ticketId: string }
  | { kind: 'REJECTED'; ticketId: string; reason?: string }
  | { kind: 'PAUSE'; ticketId: string }
  | { kind: 'RESUME'; ticketId: string }
  | { kind: 'STOP'; ticketId: string }

export type WorkflowOptions = {
  cwd: string
  ticketId?: string
  maxAttempts?: number
  resume?: boolean
  /** How many tickets the pool works at once. Forced to 1 when `ticketId` is set. */
  maxConcurrent?: number
}

export const DEFAULT_MAX_CONCURRENT = 3

export type TransitionError = {
  from: WorkflowState['status']
  event: WorkflowEvent
  message: string
}

// ---------------------------------------------------------------------------
// Pool state. `current` (ticketId -> WorkflowState) is authoritative; the
// store is a mirror written by persist() and never read back mid-run.
// ---------------------------------------------------------------------------

let current = new Map<string, WorkflowState>()
let running = false
let listeners = new Set<(state: WorkflowState) => void>()
let pendingExternal: Array<{ kind: 'PAUSE' | 'RESUME' | 'STOP'; ticketId: string }> = []
// Last status logged per ticket, so same-status writes (e.g. pause/resume) don't repeat a transcript line.
let lastLoggedStatusByTicket = new Map<string, string>()

// ---------------------------------------------------------------------------
// applyTransition -- pure, and the only place state.status changes, so the
// whole graph lives in one table that can be tested without an engine.
// ---------------------------------------------------------------------------

export function applyTransition(
  state: WorkflowState,
  event: WorkflowEvent,
  nowMs: number,
  note?: string,
): WorkflowState {
  const to = nextStatus(state.status, event)
  if (to === undefined) {
    const message = `autonomous-loop: no transition from ${state.status} on ${event}`
    const err = new Error(message) as Error & TransitionError
    err.from = state.status
    err.event = event
    err.message = message
    throw err
  }
  // attempt counts coding attempts: every edge that lands on 'coding'
  // (PREPARED, RETRY, ANSWERED, FAIL) starts a new one.
  const attempt = to === 'coding' ? state.attempt + 1 : state.attempt
  const entry = {
    from: state.status,
    event,
    to,
    attempt,
    atMs: nowMs,
    ...(note === undefined ? {} : { note }),
  }
  return {
    ...state,
    status: to,
    attempt,
    history: [...state.history, entry],
    updatedAtMs: nowMs,
  }
}

// ---------------------------------------------------------------------------
// Persistence + subscriber fan-out.
// ---------------------------------------------------------------------------

/** One transcript line per status. The switch is exhaustive, so a new status without a case fails to compile. */
export function describeTransition(state: WorkflowState): string {
  const ticket = state.ticketId ? `#${state.ticketId}` : '(no ticket)'
  const attempt = `attempt ${state.attempt}/${state.maxAttempts}`
  switch (state.status) {
    case 'claimed':
      return `autonomous-loop: claimed ${ticket}`
    case 'coding':
      return `autonomous-loop: coding ${ticket} (${attempt})`
    case 'evaluating':
      return `autonomous-loop: evaluating ${ticket}`
    case 'waiting_for_human':
      return `autonomous-loop: ${ticket} needs a human answer -- open the dashboard`
    case 'reviewing':
      return `autonomous-loop: reviewing ${ticket}`
    case 'awaiting_approval':
      return `autonomous-loop: ${ticket} is awaiting your approval -- open the dashboard`
    case 'done':
      return `autonomous-loop: ${ticket} done`
    case 'blocked':
      return `autonomous-loop: ${ticket} blocked${state.blockerReason ? ` (${state.blockerReason})` : ''}`
  }
}

async function persist(host: Host, state: WorkflowState): Promise<WorkflowState> {
  current.set(state.ticketId, state)
  await saveRuns(host, current)
  for (const listener of listeners) listener(state)

  // No `{ to: 'debug' }`: status changes are the one thing logged to the visible transcript.
  if (lastLoggedStatusByTicket.get(state.ticketId) !== state.status) {
    lastLoggedStatusByTicket.set(state.ticketId, state.status)
    await host.uiLog(describeTransition(state))
  }

  return state
}

// ---------------------------------------------------------------------------
// submitEvent — the synchronous external-event inbox.
// ---------------------------------------------------------------------------

// Synchronous and engine-free, so the dashboard's buttons can call it directly.
export function submitEvent(event: ExternalEvent): void {
  switch (event.kind) {
    case 'HUMAN_ANSWERED':
      resolveHumanAnswer(event.ticketId, event.answer)
      break
    case 'APPROVED':
      resolveApproval(event.ticketId, 'approved')
      break
    case 'REJECTED':
      resolveApproval(event.ticketId, 'rejected', event.reason)
      break
    case 'PAUSE':
      pendingExternal.push({ kind: 'PAUSE', ticketId: event.ticketId })
      break
    case 'RESUME':
      pendingExternal.push({ kind: 'RESUME', ticketId: event.ticketId })
      break
    case 'STOP':
      // Scoped to this ticket: never abort another ticket's agent or pending question.
      pendingExternal.push({ kind: 'STOP', ticketId: event.ticketId })
      abandonForTicket(event.ticketId, 'stopped by user')
      cancelForTicket(event.ticketId, 'stopped by user')
      break
  }
}

// ---------------------------------------------------------------------------
// Driver loop helpers.
// ---------------------------------------------------------------------------

async function startFresh(host: Host, options: WorkflowOptions): Promise<WorkflowState> {
  const ticket = await claimTicket(host, options.ticketId !== undefined ? { ticketId: options.ticketId } : {})
  if (ticket === undefined) {
    throw new Error('autonomous-loop: no claimable ticket')
  }
  const nowMs = await host.now()
  return createInitialState({
    ticketId: ticket.id,
    nowMs,
    ...(options.maxAttempts !== undefined ? { maxAttempts: options.maxAttempts } : {}),
    branch: ticket.branch,
  })
}

/**
 * Applies the queued events addressed to this ticket, leaving the rest. The
 * two filters run with no `await` between them, so other drivers can't interleave.
 */
async function drainExternal(host: Host, state: WorkflowState): Promise<WorkflowState> {
  const mine = pendingExternal.filter((ev) => ev.ticketId === state.ticketId)
  pendingExternal = pendingExternal.filter((ev) => ev.ticketId !== state.ticketId)

  let next = state
  for (const ev of mine) {
    if (ev.kind === 'PAUSE') {
      next = await persist(host, { ...next, paused: true })
    } else if (ev.kind === 'RESUME') {
      next = await persist(host, { ...next, paused: false })
    } else if (ev.kind === 'STOP') {
      next = await persist(host, { ...next, stopped: true })
    }
  }
  return next
}

/**
 * Re-creates the ticket's worktree if it no longer exists. A resumed run may
 * point at a directory removed since (crash, cleanup, `git worktree prune`),
 * and an agent spawned with a missing `cwd` falls back to the session's own
 * directory -- editing the main checkout instead of the isolated worktree.
 */
export async function ensureWorktree(
  host: Host,
  state: WorkflowState,
  options: WorkflowOptions,
): Promise<WorkflowState> {
  if (state.worktreePath === undefined) return state
  if (await worktreeExists(host, state.worktreePath)) return state
  const root = await repoRoot(host, options.cwd)
  const wt = await prepareWorktree(host, {
    repoRoot: root,
    branch: state.branch ?? `auto/${state.ticketId}`,
  })
  return { ...state, worktreePath: wt.path, branch: wt.branch }
}

/** Per-check cap on carried-forward eval output; the tail is kept, since errors sit at the end of a log. */
export const FAILURE_DETAIL_CHARS_PER_CHECK = 1500
/** Cap on the carried-forward reviewer critique; the head is kept, since the verdict comes first. */
export const REVIEW_FEEDBACK_CHARS = 2000

function keepTail(text: string, max: number): string {
  return text.length <= max ? text : `…(${text.length - max} earlier chars omitted)\n${text.slice(-max)}`
}

function keepHead(text: string, max: number): string {
  return text.length <= max ? text : `${text.slice(0, max)}\n…(${text.length - max} more chars omitted)`
}

/** The failed checks' output, one block per check, for the next attempt's prompt. */
export function failureDetail(report: Pick<EvalReport, 'failed'>): string | undefined {
  if (report.failed.length === 0) return undefined
  return report.failed
    .map((c) => `--- ${c.name} (exit ${c.exitCode}) ---\n${keepTail(c.output.trim(), FAILURE_DETAIL_CHARS_PER_CHECK)}`)
    .join('\n\n')
}

export function reviewFeedback(answer: string): string | undefined {
  const trimmed = answer.trim()
  return trimmed === '' ? undefined : keepHead(trimmed, REVIEW_FEEDBACK_CHARS)
}

/** The ticket (title and description) comes first, then any retry context from earlier attempts. */
export function buildCodingPrompt(state: WorkflowState, ticket?: Pick<Ticket, 'title' | 'description'>): string {
  const lines = [
    `Ticket: ${state.ticketId}`,
    `Attempt: ${state.attempt} of ${state.maxAttempts}`,
  ]
  if (ticket !== undefined) {
    lines.push(`Title: ${ticket.title}`, '', ticket.description, '')
  }
  lines.push('Implement the ticket in the current worktree.')
  if (state.humanAnswer !== undefined) {
    lines.push(`Human answered a previous blocking question: ${state.humanAnswer}`)
  }
  if (state.blockerReason !== undefined) {
    lines.push(`Previous blocker/failure reason: ${state.blockerReason}`)
  }
  if (state.lastEvalSummary !== undefined) {
    lines.push(`Previous evaluation summary: ${state.lastEvalSummary}`)
  }
  if (state.lastFailureDetail !== undefined) {
    lines.push('', 'Output of the checks that failed on the previous attempt:', state.lastFailureDetail)
  }
  if (state.lastReviewFeedback !== undefined) {
    lines.push('', 'The reviewer rejected the previous attempt. Their feedback:', state.lastReviewFeedback)
  }
  return lines.join('\n')
}

export function buildReviewPrompt(state: WorkflowState, ticket?: Pick<Ticket, 'title' | 'description'>): string {
  const lines = [`Ticket: ${state.ticketId}`]
  if (ticket !== undefined) {
    lines.push(`Title: ${ticket.title}`, '', ticket.description, '')
  }
  lines.push(
    'Review the changes in the current worktree against the ticket above.',
    'Respond with PASS or FAIL, followed by your reasons -- on FAIL, say concretely what must change.',
  )
  if (state.lastEvalSummary !== undefined) {
    lines.push(`Evaluation summary: ${state.lastEvalSummary}`)
  }
  return lines.join('\n')
}

// ---------------------------------------------------------------------------
// driveOneTicket -- drives one ticket from claim to a terminal status. Each
// step reads its inputs from `state` and writes its result back into it.
// ---------------------------------------------------------------------------

async function driveOneTicket(
  host: Host,
  options: WorkflowOptions,
  initialState: WorkflowState,
): Promise<WorkflowState> {
  let state = initialState
  while (!isTerminal(state.status)) {
    state = await drainExternal(host, state)
    if (state.stopped) break
    if (state.paused) {
      await host.sleep(500)
      continue
    }

    // These steps all touch the worktree on disk, so make sure it exists first.
    if (
      state.status === 'coding' ||
      state.status === 'evaluating' ||
      state.status === 'reviewing' ||
      state.status === 'awaiting_approval'
    ) {
      state = await ensureWorktree(host, state, options)
    }

    switch (state.status) {
      case 'claimed': {
        const ticket = await getTicket(host, state.ticketId)
        const root = await repoRoot(host, options.cwd)
        const wt = await prepareWorktree(host, {
          repoRoot: root,
          branch: ticket?.branch ?? state.branch ?? `auto/${state.ticketId}`,
        })
        state = await persist(
          host,
          applyTransition(
            { ...state, worktreePath: wt.path, branch: wt.branch },
            'PREPARED',
            await host.now(),
          ),
        )
        break
      }
      case 'coding': {
        const result = await runAgent(host, {
          kind: 'coding',
          state,
          prompt: buildCodingPrompt(state, await getTicket(host, state.ticketId)),
          description: `Code ${state.ticketId} attempt ${state.attempt}`,
        })
        // Stop aborts the agent; apply the queued STOP before the abort is misread as a coding failure.
        if (result.isAborted) {
          state = await drainExternal(host, state)
          if (state.stopped) break
        }
        const withAgent = {
          ...state,
          lastModel: result.model,
          ...(result.agentId !== undefined ? { agentId: result.agentId } : {}),
        }
        // Only a completed answer counts as finished; a refusal, error, abort, or denied spawn is a blocker.
        const codingBlockerReason =
          result.denied ??
          (result.isAborted || result.reason !== 'answer'
            ? `coding agent did not complete (reason: ${result.reason ?? 'aborted'}): ${
                result.answer || 'no answer produced'
              }`
            : undefined)
        state = codingBlockerReason !== undefined
          ? await persist(
              host,
              applyTransition(
                {
                  ...withAgent,
                  blockerReason: codingBlockerReason,
                  // Set explicitly so a leftover question from an earlier blocker isn't re-asked.
                  humanQuestion: `The coding agent could not finish: ${codingBlockerReason}. How should it proceed?`,
                },
                'BLOCKER_FOUND',
                await host.now(),
              ),
            )
          : await persist(
              host,
              applyTransition(
                // Retry context has been shown once; clear it so it can't leak into a later attempt.
                { ...withAgent, humanAnswer: undefined, lastFailureDetail: undefined, lastReviewFeedback: undefined },
                'AGENT_FINISHED',
                await host.now(),
              ),
            )
        break
      }
      case 'evaluating': {
        const worktreePath = state.worktreePath
        if (worktreePath === undefined) {
          throw new Error('autonomous-loop: evaluating with no worktreePath')
        }
        const report = await evaluateAttempt(host, { worktreePath })
        if (report.outcome === 'pass') {
          state = await persist(
            host,
            applyTransition(
              { ...state, lastEvalSummary: report.summary },
              'PASS',
              await host.now(),
            ),
          )
        } else {
          const classification = classifyFailure({
            report,
            attempt: state.attempt,
            maxAttempts: state.maxAttempts,
          })
          const event = toWorkflowEvent(classification, state.attempt, state.maxAttempts)
          state = await persist(
            host,
            applyTransition(
              {
                ...state,
                lastEvalSummary: report.summary,
                lastFailureDetail: failureDetail(report),
                blockerReason: classification.reason,
                ...(classification.question !== undefined
                  ? { humanQuestion: classification.question }
                  : {}),
              },
              event,
              await host.now(),
            ),
          )
        }
        break
      }
      case 'waiting_for_human': {
        const answer = await askHuman(host, {
          ticketId: state.ticketId,
          question: state.humanQuestion ?? 'Need input to continue.',
        })
        state =
          answer.answer === ''
            ? await persist(host, applyTransition(state, 'CANCELLED', await host.now()))
            : await persist(
                host,
                applyTransition(
                  // Clear the answered question so a later blocker can't re-ask it.
                  { ...state, humanAnswer: answer.answer, humanQuestion: undefined },
                  'ANSWERED',
                  await host.now(),
                ),
              )
        break
      }
      case 'reviewing': {
        const result = await runAgent(host, {
          kind: 'review',
          state,
          prompt: buildReviewPrompt(state, await getTicket(host, state.ticketId)),
          description: `Review ${state.ticketId}`,
        })
        if (result.isAborted) {
          state = await drainExternal(host, state) // same STOP-vs-failure ordering as 'coding'
          if (state.stopped) break
        }
        // A review that never completed has no verdict: treat it as FAIL, but record why.
        const reviewBlockerReason =
          result.denied ??
          (result.isAborted || result.reason !== 'answer'
            ? `review agent did not complete (reason: ${result.reason ?? 'aborted'}): ${
                result.answer || 'no answer produced'
              }`
            : undefined)
        const passVerdict =
          reviewBlockerReason === undefined &&
          /\bpass\b/i.test(result.answer) &&
          !/\bfail\b/i.test(result.answer)
        // Cap review failures at maxAttempts, as evaluation does, so the cycle can't run forever.
        const reviewEvent = passVerdict
          ? 'PASS'
          : state.attempt >= state.maxAttempts
            ? 'EXHAUSTED'
            : 'FAIL'
        state = await persist(
          host,
          applyTransition(
            {
              ...state,
              lastModel: result.model,
              lastReviewFeedback: passVerdict ? undefined : reviewFeedback(result.answer),
              ...(reviewBlockerReason !== undefined ? { blockerReason: reviewBlockerReason } : {}),
            },
            reviewEvent,
            await host.now(),
          ),
        )
        break
      }
      case 'awaiting_approval': {
        const diff = state.worktreePath !== undefined ? await diffStat(host, state.worktreePath) : undefined
        const answer = await requestApproval(host, {
          ticketId: state.ticketId,
          summary: state.lastEvalSummary ?? '',
          ...(diff !== undefined
            ? { diffStat: `${diff.filesChanged} files, +${diff.insertions}/-${diff.deletions}` }
            : {}),
        })
        state = await persist(
          host,
          applyTransition(
            state,
            answer.decision === 'approved' ? 'APPROVED' : 'REJECTED',
            await host.now(),
          ),
        )
        break
      }
      default:
        break
    }
  }

  if (state.stopped && !isTerminal(state.status)) {
    // STOP is a kill switch, not a graph edge. Force a terminal status so a
    // later resume doesn't pick the ticket up again -- the one deliberate
    // exception to applyTransition owning every status change.
    state = await persist(host, {
      ...state,
      status: 'blocked',
      stopped: false,
      updatedAtMs: await host.now(),
    })
  }

  await updateTicket(host, state.ticketId, {
    status: state.status === 'done' ? 'done' : 'blocked',
  }).catch(() => undefined)

  return state
}

// ---------------------------------------------------------------------------
// runWorkflow -- the pool scheduler. Resumes unfinished runs, then keeps up
// to `maxConcurrent` tickets active, refilling a slot as soon as one
// finishes, until nothing is left to claim.
// ---------------------------------------------------------------------------

export async function runWorkflow(
  host: Host,
  options: WorkflowOptions,
): Promise<void> {
  if (running) {
    throw new Error('autonomous-loop: workflow already running')
  }
  running = true
  try {
    const maxConcurrent = options.ticketId !== undefined ? 1 : (options.maxConcurrent ?? DEFAULT_MAX_CONCURRENT)

    const loaded = options.resume !== false ? await loadRuns(host) : new Map<string, WorkflowState>()
    // A single-ticket run resumes only its own saved run.
    const relevantLoaded = options.ticketId !== undefined
      ? new Map([...loaded].filter(([ticketId]) => ticketId === options.ticketId))
      : loaded

    // Finished runs aren't resumable; drop them from the snapshot.
    let archived = false
    for (const [ticketId, run] of relevantLoaded) {
      if (isTerminal(run.status)) {
        archived = true
        continue
      }
      current.set(ticketId, run)
    }
    if (archived) await saveRuns(host, current)

    const active = new Map<string, Promise<void>>()
    const launch = (state: WorkflowState): void => {
      const ticketId = state.ticketId
      active.set(
        ticketId,
        driveOneTicket(host, options, state).then(() => {
          active.delete(ticketId)
        }),
      )
    }
    for (const state of current.values()) launch(state)

    if (options.ticketId !== undefined) {
      // Claim at most once and never refill: claiming by id skips the
      // open-status check, so the refill loop would re-claim this same
      // finished ticket forever.
      if (active.size === 0) {
        const fresh = await startFresh(host, options).catch(() => undefined)
        if (fresh !== undefined) {
          current.set(fresh.ticketId, fresh)
          await saveRuns(host, current)
          launch(fresh)
        }
      }
      if (active.size > 0) await Promise.race(active.values())
      return
    }

    for (;;) {
      while (active.size < maxConcurrent) {
        const fresh = await startFresh(host, options).catch(() => undefined)
        if (fresh === undefined) break // nothing claimable right now
        current.set(fresh.ticketId, fresh)
        await saveRuns(host, current)
        launch(fresh)
      }
      if (active.size === 0) break // nothing running and nothing claimable
      await Promise.race(active.values())
    }
  } finally {
    running = false
  }
}

// ---------------------------------------------------------------------------
// Readers, subscribers, and teardown.
// ---------------------------------------------------------------------------

/** Every run the pool holds this session, in claim order. */
export function currentStates(): readonly WorkflowState[] {
  return [...current.values()]
}

export function isRunning(): boolean {
  return running
}

export function subscribe(listener: (state: WorkflowState) => void): () => void {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

export function reset(): void {
  current = new Map()
  running = false
  listeners = new Set()
  pendingExternal = []
  lastLoggedStatusByTicket = new Map()
}

