// hooks/approval.ts — the human gates: approve/reject a finished ticket, and
// answer a blocking question. Each can be settled from a dialog or the dashboard.

import type { Host } from './host'

export type ApprovalDecision = 'approved' | 'rejected'

export type ApprovalRequest = {
  ticketId: string
  summary: string
  diffStat?: string
}

export type ApprovalAnswer = {
  decision: ApprovalDecision
  via: 'dialog' | 'dashboard'
  answeredAtMs: number
  note?: string
}

export type HumanQuestion = {
  ticketId: string
  question: string
  options?: readonly string[]
}

export type HumanAnswer = {
  answer: string
  via: 'dialog' | 'dashboard'
  answeredAtMs: number
}

export const APPROVE_LABEL = 'Approve'
export const REJECT_LABEL = 'Reject'

// ---------------------------------------------------------------------------
// Approval requests, keyed by ticketId: several tickets can await approval at
// once, and one ticket's Approve/Reject must never resolve another's.
// ---------------------------------------------------------------------------

const approvalReqs = new Map<string, ApprovalRequest>()
const approvalResolves = new Map<string, (answer: ApprovalAnswer) => void>()

export function requestApproval(
  host: Host,
  request: ApprovalRequest,
): Promise<ApprovalAnswer> {
  return new Promise<ApprovalAnswer>((resolve) => {
    const ticketId = request.ticketId
    approvalReqs.set(ticketId, request)
    approvalResolves.set(ticketId, (answer: ApprovalAnswer) => {
      approvalReqs.delete(ticketId)
      approvalResolves.delete(ticketId)
      resolve(answer)
    })
    host
      .uiAsk(`Approve "${request.summary}"?`, [APPROVE_LABEL, REJECT_LABEL])
      .then(async (label) => {
        const answeredAtMs = await host.now()
        approvalResolves.get(ticketId)?.({
          decision: label === APPROVE_LABEL ? 'approved' : 'rejected',
          via: 'dialog',
          answeredAtMs,
        })
      })
      .catch(() => {
        // Dismissed or a -p run: no one to ask. Leave the dashboard-driven
        // deferred pending; do NOT reject the returned promise.
      })
  })
}

export function resolveApproval(ticketId: string, decision: ApprovalDecision, note?: string): boolean {
  const resolve = approvalResolves.get(ticketId)
  if (!resolve) return false
  resolve({
    decision,
    via: 'dashboard',
    // Called synchronously from a Button onPress, where no engine clock is reachable.
    answeredAtMs: Date.now(),
    ...(note !== undefined ? { note } : {}),
  })
  return true
}

export function isAwaitingApproval(ticketId: string): boolean {
  return approvalReqs.has(ticketId)
}

export function pendingApproval(ticketId: string): ApprovalRequest | undefined {
  return approvalReqs.get(ticketId)
}

// ---------------------------------------------------------------------------
// Blocking questions (free-text answer), keyed by ticketId for the same reason.
// ---------------------------------------------------------------------------

const humanQs = new Map<string, HumanQuestion>()
const humanResolves = new Map<string, (answer: HumanAnswer) => void>()

export function askHuman(host: Host, question: HumanQuestion): Promise<HumanAnswer> {
  return new Promise<HumanAnswer>((resolve) => {
    const ticketId = question.ticketId
    humanQs.set(ticketId, question)
    humanResolves.set(ticketId, (answer: HumanAnswer) => {
      humanQs.delete(ticketId)
      humanResolves.delete(ticketId)
      resolve(answer)
    })
    host
      .uiAsk(question.question, question.options)
      .then(async (answer) => {
        const answeredAtMs = await host.now()
        humanResolves.get(ticketId)?.({
          answer,
          via: 'dialog',
          answeredAtMs,
        })
      })
      .catch(() => {
        // Dismissed or a -p run: no one to ask. Leave the dashboard-driven
        // deferred pending; do NOT reject the returned promise.
      })
  })
}

export function resolveHumanAnswer(ticketId: string, answer: string): boolean {
  const resolve = humanResolves.get(ticketId)
  if (!resolve) return false
  resolve({ answer, via: 'dashboard', answeredAtMs: Date.now() })
  return true
}

export function isAwaitingHuman(ticketId: string): boolean {
  return humanQs.has(ticketId)
}

export function pendingQuestion(ticketId: string): HumanQuestion | undefined {
  return humanQs.get(ticketId)
}

// ---------------------------------------------------------------------------
// Teardown
// ---------------------------------------------------------------------------

/**
 * Settles one ticket's pending request(s) on that ticket's Stop, leaving every
 * other ticket untouched. A cancelled question settles with answer '', which
 * workflow.ts treats as CANCELLED.
 */
export function cancelForTicket(ticketId: string, reason: string): void {
  approvalResolves.get(ticketId)?.({ decision: 'rejected', via: 'dashboard', answeredAtMs: Date.now(), note: reason })
  humanResolves.get(ticketId)?.({ answer: '', via: 'dashboard', answeredAtMs: Date.now() })
  approvalReqs.delete(ticketId)
  approvalResolves.delete(ticketId)
  humanQs.delete(ticketId)
  humanResolves.delete(ticketId)
}

/** Settles every ticket's pending request(s), on full teardown. */
export function cancelAll(reason: string): void {
  for (const ticketId of new Set([...approvalReqs.keys(), ...humanQs.keys()])) {
    cancelForTicket(ticketId, reason)
  }
}

