// hooks/dashboard/render.tsx — draws the dashboard pane: the LOOP banner and
// one card per active ticket, with its buttons.

import type { EngineInterface, Frozen, RenderElement, RenderInput } from 'claude-code'
import type { WorkflowState } from '../state'
import type { ExternalEvent } from '../workflow'
import * as animation from '../animation'

/** The id this plugin opens its Pane with via `$.ui.open({ id: PANE_ID })`. */
export const PANE_ID = 'autonomous-loop'
export const PANE_TITLE = 'Autonomous Loop'

export type DashboardProps = {
  /** Every active run, in claim order. */
  states: readonly WorkflowState[]
  emit: (event: ExternalEvent) => void
  awaitingApproval: (ticketId: string) => boolean
  awaitingHuman: (ticketId: string) => boolean
}

/** True when this render event is for this plugin's own pane, not another plugin's. */
export function isOwnPane(e: Frozen<RenderInput<'Pane'>>): boolean {
  return e.component === 'Pane' && e.requestId === PANE_ID
}

// Below this pane width, buttons stack vertically instead of side by side.
const NARROW_COLUMNS = 48

/** One dim `label: value` line, truncated rather than wrapped so long values keep the layout intact. */
function FieldLine(
  Text: ReturnType<EngineInterface['ui']['resolve']>['Text'],
  label: string,
  value: string,
): RenderElement {
  return (
    <Text dimColor wrap="truncate-end">
      {label}: {value}
    </Text>
  )
}

/**
 * One ticket's card: fields, blocker or question, buttons, and history.
 * Every button emits an event carrying this card's own ticketId; the
 * dashboard never changes WorkflowState directly.
 */
function RunCard(
  elements: ReturnType<EngineInterface['ui']['resolve']>,
  state: WorkflowState,
  isNarrow: boolean,
  props: DashboardProps,
): RenderElement {
  const { Box, Text, Button } = elements
  const Input = 'Input' in elements ? elements.Input : undefined
  const awaitingApproval = props.awaitingApproval(state.ticketId)
  const awaitingHuman = props.awaitingHuman(state.ticketId)

  return (
    <Box flexDirection="column" marginTop={1} paddingX={1}>
      <Text bold>
        #{state.ticketId} — {statusLine(state)}
      </Text>

      <Box flexDirection="column">
        {state.branch && FieldLine(Text, 'branch', state.branch)}
        {state.lastModel && FieldLine(Text, 'model', state.lastModel)}
        {state.agentId && FieldLine(Text, 'agent', state.agentId)}
        {state.lastEvalSummary && FieldLine(Text, 'eval', state.lastEvalSummary)}
      </Box>

      {state.blockerReason && (
        <Box marginTop={1}>
          <Text wrap="wrap">blocker: {state.blockerReason}</Text>
        </Box>
      )}
      {awaitingHuman && state.humanQuestion && (
        <Box marginTop={1}>
          <Text wrap="wrap">question: {state.humanQuestion}</Text>
        </Box>
      )}

      <Box
        flexDirection={isNarrow ? 'column' : 'row'}
        gap={isNarrow ? 0 : 1}
        marginTop={1}
      >
        <Button
          label={state.paused ? 'Resume' : 'Pause'}
          onPress={() => props.emit({ kind: state.paused ? 'RESUME' : 'PAUSE', ticketId: state.ticketId })}
        />
        <Button label="Stop" onPress={() => props.emit({ kind: 'STOP', ticketId: state.ticketId })} />
        {awaitingApproval && (
          <Button label="Approve" onPress={() => props.emit({ kind: 'APPROVED', ticketId: state.ticketId })} />
        )}
        {awaitingApproval && (
          <Button label="Reject" onPress={() => props.emit({ kind: 'REJECTED', ticketId: state.ticketId })} />
        )}
      </Box>

      {awaitingHuman && Input && (
        <Box marginTop={1}>
          <Input
            key={`answer-${state.ticketId}`}
            label="Answer"
            placeholder="Type your answer and press Enter"
            submitLabel="answer"
            onSubmit={(value: string) => props.emit({ kind: 'HUMAN_ANSWERED', ticketId: state.ticketId, answer: value })}
          />
        </Box>
      )}

      <Box flexDirection="column" marginTop={1}>
        <Text bold dimColor>history</Text>
        {historyLines(state).map((line, i) => (
          <Text key={String(i)} dimColor wrap="truncate-end">
            {line}
          </Text>
        ))}
      </Box>
    </Box>
  )
}

/**
 * The pane body: title, LOOP banner, summary, then one card per active ticket.
 *
 * `elements` comes from `$.ui.resolve(e)` in index.ts rather than an import,
 * so the same JSX works on every surface. Every Box sets `flexDirection`
 * explicitly because the layout engine defaults to `row`.
 */
export function renderDashboard(
  elements: ReturnType<EngineInterface['ui']['resolve']>,
  e: Frozen<RenderInput<'Pane'>>,
  props: DashboardProps,
): RenderElement {
  const { Box, Text } = elements
  const isNarrow = e.props.bodyColumns < NARROW_COLUMNS

  return (
    <Box flexDirection="column" paddingX={1} width={e.props.bodyColumns}>
      <Text bold>{PANE_TITLE}</Text>
      <Box flexDirection="column">
        {animation.currentFrame().map((line, i) => (
          <Text key={String(i)} color="#CC785C" wrap="truncate">
            {line}
          </Text>
        ))}
      </Box>
      <Text dimColor>{summaryLine(props.states)}</Text>

      {props.states.map((state) => (
        <Box key={state.ticketId} flexDirection="column">
          {RunCard(elements, state, isNarrow, props)}
        </Box>
      ))}
    </Box>
  )
}

export function summaryLine(states: readonly WorkflowState[]): string {
  if (states.length === 0) return 'no active runs'
  return `${states.length} active run${states.length === 1 ? '' : 's'}`
}

export function statusLine(state: WorkflowState): string {
  return `${state.status} (attempt ${state.attempt}/${state.maxAttempts})`
}

/** The last `limit` transitions, oldest first. */
export function historyLines(state: WorkflowState, limit = 10): readonly string[] {
  return state.history
    .slice(-limit)
    .map((h) => `${h.from} --${h.event}--> ${h.to}`)
}

