// hooks/host.ts — the engine capabilities the loop uses, as a plain object.
//
// Claude Code statically checks a hooks module before loading it, and refuses
// one that uses `$` as a value: assigning it, passing it to a function,
// spreading or returning it. `$` may only appear as a literal
// `$.noun.method(...)` call. That lets the engine list exactly which
// capabilities a plugin uses.
//
// So index.ts builds a `Host` inline in session.start: an object of small
// closures, each a literal `$` call (`now: () => $.clock.now()`). The object
// is not `$`, so it can be passed into workflow.ts and everything it calls,
// and tests can pass a fake one instead.

import type { EngineInterface } from 'claude-code'

export type Host = {
  now: EngineInterface['clock']['now']
  sleep: EngineInterface['clock']['sleep']
  every: EngineInterface['clock']['every']
  storeGet: EngineInterface['store']['get']
  storeSet: EngineInterface['store']['set']
  storeDelete: EngineInterface['store']['delete']
  run: EngineInterface['process']['run']
  fsExists: EngineInterface['fs']['exists']
  spawnAgent: EngineInterface['agent']['spawn']
  listAgents: EngineInterface['agent']['list']
  uiAsk: EngineInterface['ui']['ask']
  uiOpen: EngineInterface['ui']['open']
  uiInvalidate: EngineInterface['ui']['invalidate']
  uiLog: EngineInterface['ui']['log']
}

// There is deliberately no `hostOf($)` builder: calling it would pass `$` as
// an argument, the very thing the engine refuses. Only the type lives here.

