// hooks/state.ts -- the workflow's types, its transition table (the graph),
// model routing, and persistence of per-ticket run state.

import type { Host } from './host'

export type WorkflowStatus =
  | 'claimed'
  | 'coding'
  | 'evaluating'
  | 'waiting_for_human'
  | 'reviewing'
  | 'awaiting_approval'
  | 'done'
  | 'blocked'

export type WorkflowEvent =
  | 'PREPARED'
  | 'AGENT_FINISHED'
  | 'BLOCKER_FOUND'
  | 'PASS'
  | 'RETRY'
  | 'EXHAUSTED'
  | 'ANSWERED'
  | 'CANCELLED'
  | 'FAIL'
  | 'APPROVED'
  | 'REJECTED'

export type ModelTier = 'haiku' | 'sonnet' | 'opus'

export type TransitionTable = Readonly<
  Record<WorkflowStatus, Readonly<Partial<Record<WorkflowEvent, WorkflowStatus>>>>
>

export type HistoryEntry = {
  from: WorkflowStatus
  event: WorkflowEvent
  to: WorkflowStatus
  attempt: number
  atMs: number
  note?: string
}

export type WorkflowState = {
  ticketId: string
  status: WorkflowStatus
  attempt: number
  maxAttempts: number
  worktreePath?: string
  branch?: string
  agentId?: string
  lastModel?: ModelTier
  lastEvalSummary?: string
  /** Failed checks' output (tail, capped) from the last evaluation; cleared after the next coding attempt. */
  lastFailureDetail?: string
  /** The reviewer's critique (capped) from a review that did not pass; cleared after the next coding attempt. */
  lastReviewFeedback?: string
  blockerReason?: string
  humanQuestion?: string
  humanAnswer?: string
  approval?: 'pending' | 'approved' | 'rejected'
  paused: boolean
  stopped: boolean
  history: HistoryEntry[]
  leaseExpiresAtMs: number
  createdAtMs: number
  updatedAtMs: number
}

export type ModelRoutingState = Pick<WorkflowState, 'status' | 'attempt'>

export const RUNS_STORE_KEY = 'autonomous-loop/runs'
export const DEFAULT_MAX_ATTEMPTS = 3
export const DEFAULT_LEASE_MS = 120_000
export const TERMINAL_STATUSES: readonly WorkflowStatus[] = ['done', 'blocked']

export const transitions: TransitionTable = {
  claimed: { PREPARED: 'coding' },
  coding: { AGENT_FINISHED: 'evaluating', BLOCKER_FOUND: 'waiting_for_human' },
  evaluating: {
    PASS: 'reviewing',
    RETRY: 'coding',
    BLOCKER_FOUND: 'waiting_for_human',
    EXHAUSTED: 'blocked',
  },
  waiting_for_human: { ANSWERED: 'coding', CANCELLED: 'blocked' },
  // EXHAUSTED caps the reviewing -> coding -> evaluating -> reviewing cycle at maxAttempts.
  reviewing: { PASS: 'awaiting_approval', FAIL: 'coding', EXHAUSTED: 'blocked' },
  awaiting_approval: { APPROVED: 'done', REJECTED: 'blocked' },
  done: {},
  blocked: {},
}

export function createInitialState(args: {
  ticketId: string
  nowMs: number
  maxAttempts?: number
  branch?: string
}): WorkflowState {
  return {
    ticketId: args.ticketId,
    status: 'claimed',
    attempt: 0,
    maxAttempts: args.maxAttempts ?? DEFAULT_MAX_ATTEMPTS,
    paused: false,
    stopped: false,
    history: [],
    leaseExpiresAtMs: args.nowMs + DEFAULT_LEASE_MS,
    createdAtMs: args.nowMs,
    updatedAtMs: args.nowMs,
    ...(args.branch !== undefined ? { branch: args.branch } : {}),
  }
}

export function nextStatus(
  status: WorkflowStatus,
  event: WorkflowEvent,
): WorkflowStatus | undefined {
  return transitions[status][event]
}

export function isTerminal(status: WorkflowStatus): boolean {
  return TERMINAL_STATUSES.includes(status)
}

/**
 * Model routing: reviews always use opus; the first coding attempt uses
 * sonnet, and a retry escalates to opus, since a failure suggests a harder task.
 */
export function pickModel(state: ModelRoutingState): ModelTier {
  if (state.status === 'reviewing') return 'opus'
  return state.attempt > 1 ? 'opus' : 'sonnet'
}

/**
 * Reads every persisted run, keyed by ticketId. A malformed entry is dropped
 * rather than thrown, so one corrupt record never blocks the others' resume.
 */
export async function loadRuns(host: Host): Promise<Map<string, WorkflowState>> {
  const raw = await host.storeGet(RUNS_STORE_KEY)
  if (raw === undefined || raw === null || typeof raw !== 'object') return new Map()
  const runs = new Map<string, WorkflowState>()
  for (const [ticketId, value] of Object.entries(raw as Record<string, unknown>)) {
    if (value !== null && typeof value === 'object' && 'status' in value) {
      runs.set(ticketId, value as WorkflowState)
    }
  }
  return runs
}

/**
 * Writes the whole runs map as one snapshot. The store has no compare-and-set,
 * so a read-modify-write would race between concurrent tickets; the caller
 * keeps the authoritative map in memory and every save is a plain overwrite.
 */
export async function saveRuns(host: Host, runs: ReadonlyMap<string, WorkflowState>): Promise<void> {
  await host.storeSet(RUNS_STORE_KEY, Object.fromEntries(runs))
}

