// hooks/ticket.ts — the ticket queue: a demo list kept in the plugin's store,
// with claims, leases, and updates serialized through one lock.

import type { Host } from './host'

export type TicketStatus = 'open' | 'claimed' | 'in_progress' | 'blocked' | 'done'

export type Ticket = {
  id: string
  title: string
  description: string
  status: TicketStatus
  branch: string
  assignee?: string
  claimedAtMs?: number
  leaseExpiresAtMs?: number
  updatedAtMs: number
}

export const TICKET_STORE_KEY = 'autonomous-loop/tickets'

const DEFAULT_TICKET_LEASE_MS = 120_000

export const DEMO_TICKETS: readonly Ticket[] = [
  {
    id: 'DEMO-1',
    title: 'Add a health-check endpoint',
    description: 'Expose GET /health returning { ok: true } for uptime checks.',
    status: 'open',
    branch: 'auto/demo-1-health-check',
    updatedAtMs: 0,
  },
  // Small and self-contained: sized to run the full graph and pass first time.
  {
    id: 'DEMO-2',
    title: 'Add a formatDuration utility',
    description:
      'Add a pure function `formatDuration(ms: number): string` to a new file `hooks/format-duration.ts`. ' +
      'It formats a non-negative millisecond duration as compact `Xh Ym Zs`-style text, omitting any ' +
      'leading zero unit (e.g. 1500 -> "1s", 61000 -> "1m 1s", 3661000 -> "1h 1m 1s"), and returns "0s" ' +
      'for 0. Add `hooks/format-duration.test.ts` with real `node:test` cases covering at least: 0, under ' +
      'a minute, exactly one minute, and over an hour. Do not modify any other file.',
    status: 'open',
    branch: 'auto/demo-2-format-duration',
    updatedAtMs: 0,
  },
]

// The store is one JSON list with only get/set, so every change is a
// whole-list read-modify-write with awaits in between. Unserialized, two
// concurrent writers (pool drivers, heartbeat renewals) could each read the
// same list and the later write would drop the earlier change -- e.g. a lease
// renewal reverting a fresh claim to `open`. Every public function below runs
// under `withTicketLock`, a promise-chain mutex. It is not re-entrant, so
// locked code calls only the `*Unlocked` helpers. It protects one process only.

let lockTail: Promise<unknown> = Promise.resolve()

/** Runs `fn` once every earlier locked call has settled; a failure never wedges the queue. */
export function withTicketLock<T>(fn: () => Promise<T>): Promise<T> {
  const run = lockTail.then(fn, fn)
  lockTail = run.catch(() => undefined)
  return run
}

async function listTicketsUnlocked(host: Host): Promise<Ticket[]> {
  const stored = await host.storeGet(TICKET_STORE_KEY)
  if (!Array.isArray(stored) || stored.length === 0) {
    await host.storeSet(TICKET_STORE_KEY, DEMO_TICKETS)
    return [...DEMO_TICKETS]
  }
  const storedList = stored as Ticket[]
  // Append demo tickets added since the store was seeded; existing entries
  // (and their live status/claim/lease) are never touched.
  const knownIds = new Set(storedList.map((t) => t.id))
  const missing = DEMO_TICKETS.filter((t) => !knownIds.has(t.id))
  if (missing.length === 0) return storedList
  const merged = [...storedList, ...missing]
  await host.storeSet(TICKET_STORE_KEY, merged)
  return merged
}

async function updateTicketUnlocked(
  host: Host,
  ticketId: string,
  patch: Partial<Omit<Ticket, 'id'>>,
): Promise<Ticket> {
  const list = await listTicketsUnlocked(host)
  const index = list.findIndex((t) => t.id === ticketId)
  if (index === -1) {
    throw new Error(`ticket.ts: unknown ticketId ${ticketId}`)
  }
  const existing = list[index] as Ticket
  const updated: Ticket = {
    ...existing,
    ...patch,
    updatedAtMs: await host.now(),
  }
  const next = [...list]
  next[index] = updated
  await host.storeSet(TICKET_STORE_KEY, next)
  return updated
}

export function listTickets(host: Host): Promise<Ticket[]> {
  return withTicketLock(() => listTicketsUnlocked(host))
}

export function seedTickets(
  host: Host,
  tickets: readonly Ticket[],
): Promise<void> {
  return withTicketLock(() => host.storeSet(TICKET_STORE_KEY, tickets))
}

export async function getTicket(
  host: Host,
  ticketId: string,
): Promise<Ticket | undefined> {
  return (await listTickets(host)).find((t) => t.id === ticketId)
}

export async function nextOpenTicket(host: Host): Promise<Ticket | undefined> {
  return (await listTickets(host)).find((t) => t.status === 'open')
}

/** Finds and claims a ticket under one lock hold, so no other writer can slip in between. */
export function claimTicket(
  host: Host,
  args?: { ticketId?: string; assignee?: string; leaseMs?: number },
): Promise<Ticket | undefined> {
  return withTicketLock(async () => {
    const list = await listTicketsUnlocked(host)
    const ticket = args?.ticketId !== undefined
      ? list.find((t) => t.id === args.ticketId)
      : list.find((t) => t.status === 'open')
    if (ticket === undefined) return undefined

    const leaseMs = args?.leaseMs ?? DEFAULT_TICKET_LEASE_MS
    const nowMs = await host.now()

    return updateTicketUnlocked(host, ticket.id, {
      status: 'claimed',
      claimedAtMs: nowMs,
      leaseExpiresAtMs: nowMs + leaseMs,
      ...(args?.assignee !== undefined ? { assignee: args.assignee } : {}),
    })
  })
}

export function updateTicket(
  host: Host,
  ticketId: string,
  patch: Partial<Omit<Ticket, 'id'>>,
): Promise<Ticket> {
  return withTicketLock(() => updateTicketUnlocked(host, ticketId, patch))
}

export function renewLease(
  host: Host,
  ticketId: string,
  leaseMs: number,
): Promise<Ticket | undefined> {
  return withTicketLock(async () => {
    const ticket = (await listTicketsUnlocked(host)).find((t) => t.id === ticketId)
    if (ticket === undefined) return undefined
    const nowMs = await host.now()
    return updateTicketUnlocked(host, ticketId, { leaseExpiresAtMs: nowMs + leaseMs })
  })
}

export async function releaseTicket(host: Host, ticketId: string): Promise<void> {
  try {
    await updateTicket(host, ticketId, {
      status: 'open',
      assignee: undefined,
      claimedAtMs: undefined,
      leaseExpiresAtMs: undefined,
    })
  } catch {
    // Unknown ticket: nothing to release.
  }
}

