// hooks/worktree.ts — thin wrapper over git: one worktree per ticket.
// Every command runs as argv (no shell) with an explicit cwd.

import type { Host } from './host'

export type Worktree = {
  path: string
  branch: string
  baseRef: string
  createdAtMs: number
}

export type DiffStat = {
  filesChanged: number
  insertions: number
  deletions: number
}

export type PrepareWorktreeArgs = {
  repoRoot: string
  branch: string
  baseRef?: string // default 'HEAD'
  root?: string // parent dir for worktrees; default `${repoRoot}/.worktrees`
}

export const WORKTREE_DIR_NAME = '.worktrees'

export async function repoRoot(host: Host, cwd: string): Promise<string> {
  const r = await host.run(['git', 'rev-parse', '--show-toplevel'], { cwd })
  if (r.exitCode !== 0) {
    throw new Error(r.stderr || 'git rev-parse failed')
  }
  return r.stdout.trim()
}

export function worktreeExists(host: Host, path: string): Promise<boolean> {
  return host.fsExists(path)
}

export async function listWorktrees(
  host: Host,
  repoRoot: string,
): Promise<Worktree[]> {
  const r = await host.run(['git', 'worktree', 'list', '--porcelain'], {
    cwd: repoRoot,
  })
  if (r.exitCode !== 0) {
    throw new Error(r.stderr || 'git worktree list failed')
  }

  // Porcelain output: blank-line-separated blocks of `worktree <path>` plus
  // `branch refs/heads/<name>` or `detached`. It has no creation time, so
  // createdAtMs is "observed now".
  const worktrees: Worktree[] = []
  const blocks = r.stdout.split(/\r?\n\r?\n/)
  for (const block of blocks) {
    const lines = block.split(/\r?\n/).filter((line) => line.length > 0)
    if (lines.length === 0) continue
    const worktreeLine = lines.find((line) => line.startsWith('worktree '))
    if (worktreeLine === undefined) continue
    const path = worktreeLine.slice('worktree '.length)
    const branchLine = lines.find((line) => line.startsWith('branch '))
    const branch =
      branchLine !== undefined
        ? branchLine.slice('branch '.length).replace(/^refs\/heads\//, '')
        : 'detached'
    worktrees.push({
      path,
      branch,
      baseRef: '',
      createdAtMs: await host.now(),
    })
  }
  return worktrees
}

/**
 * True when `branch` already exists as a local ref. `git worktree add -b`
 * refuses an existing branch, which is what remains when a worktree
 * directory was removed but its branch was not.
 */
async function branchExists(host: Host, args: { repoRoot: string; branch: string }): Promise<boolean> {
  const r = await host.run(['git', 'rev-parse', '--verify', '--quiet', `refs/heads/${args.branch}`], {
    cwd: args.repoRoot,
  })
  return r.exitCode === 0
}

export async function prepareWorktree(
  host: Host,
  args: PrepareWorktreeArgs,
): Promise<Worktree> {
  const baseRef = args.baseRef ?? 'HEAD'
  const root = args.root ?? `${args.repoRoot}/${WORKTREE_DIR_NAME}`
  const path = `${root}/${args.branch}`

  if (await worktreeExists(host, path)) {
    return { path, branch: args.branch, baseRef, createdAtMs: await host.now() }
  }

  const alreadyHasBranch = await branchExists(host, { repoRoot: args.repoRoot, branch: args.branch })
  const argv = alreadyHasBranch
    ? ['git', 'worktree', 'add', path, args.branch]
    : ['git', 'worktree', 'add', '-b', args.branch, path, baseRef]
  const r = await host.run(argv, { cwd: args.repoRoot })
  if (r.exitCode !== 0) {
    throw new Error(`git worktree add failed: ${r.stderr}`)
  }

  return { path, branch: args.branch, baseRef, createdAtMs: await host.now() }
}

export async function cleanupWorktree(
  host: Host,
  worktreePath: string,
  options?: { removeBranch?: boolean; branch?: string },
): Promise<void> {
  try {
    // `worktreePath` is about to be deleted, so run from its parent (the
    // worktrees root), which `git worktree remove` leaves in place.
    const parent = worktreePath.slice(0, worktreePath.lastIndexOf('/')) || '/'

    await host
      .run(['git', 'worktree', 'remove', '--force', worktreePath], { cwd: parent })
      .catch(() => undefined)

    if (options?.removeBranch && options.branch) {
      await host
        .run(['git', 'branch', '-D', options.branch], { cwd: parent })
        .catch(() => undefined)
    }
  } catch {
    // never throw
  }
}

export async function diffStat(
  host: Host,
  worktreePath: string,
): Promise<DiffStat> {
  const r = await host.run(['git', 'diff', '--shortstat'], {
    cwd: worktreePath,
  })

  const filesMatch = r.stdout.match(/(\d+) files? changed/)
  const insertionsMatch = r.stdout.match(/(\d+) insertions?\(\+\)/)
  const deletionsMatch = r.stdout.match(/(\d+) deletions?\(-\)/)

  return {
    filesChanged: filesMatch ? Number(filesMatch[1]) : 0,
    insertions: insertionsMatch ? Number(insertionsMatch[1]) : 0,
    deletions: deletionsMatch ? Number(deletionsMatch[1]) : 0,
  }
}

