// hooks/eval.ts — runs the checks (typecheck, tests) in a ticket's worktree
// and summarises the result.

import type { Host } from './host'

export type EvalCheck = {
  name: string
  command: readonly string[] // argv for $.process.run
  required: boolean // a failed required check fails the attempt
  timeoutMs?: number // default 120_000
}

export type EvalCheckResult = {
  name: string
  exitCode: number
  passed: boolean
  required: boolean
  output: string // stdout + stderr, trimmed to 4000 chars
  durationMs: number
}

export type EvalOutcome = 'pass' | 'fail'

export type EvalReport = {
  outcome: EvalOutcome
  checks: readonly EvalCheckResult[]
  failed: readonly EvalCheckResult[]
  summary: string
  evaluatedAtMs: number
}

const DEFAULT_TIMEOUT_MS = 120_000
const MAX_OUTPUT_CHARS = 4000

export const DEFAULT_CHECKS: readonly EvalCheck[] = [
  { name: 'typecheck', command: ['npx', 'tsc', '--noEmit'], required: true, timeoutMs: 120_000 },
  { name: 'test', command: ['npm', 'test', '--silent'], required: true, timeoutMs: 120_000 },
]

export async function evaluateAttempt(
  host: Host,
  args: { worktreePath: string; checks?: readonly EvalCheck[] },
): Promise<EvalReport> {
  const list = args.checks ?? DEFAULT_CHECKS
  const results: EvalCheckResult[] = []

  for (const check of list) {
    const startedAtMs = await host.now()
    // process.run rejects (rather than resolving non-zero) on a timeout;
    // treat that as an ordinary failed check instead of letting it escape.
    let outcome: { exitCode: number; stdout: string; stderr: string }
    try {
      outcome = await host.run(check.command, {
        cwd: args.worktreePath,
        timeoutMs: check.timeoutMs ?? DEFAULT_TIMEOUT_MS,
      })
    } catch (error) {
      outcome = { exitCode: -1, stdout: '', stderr: `process.run failed: ${String(error)}` }
    }
    const finishedAtMs = await host.now()
    results.push({
      name: check.name,
      exitCode: outcome.exitCode,
      passed: outcome.exitCode === 0,
      required: check.required,
      output: (outcome.stdout + outcome.stderr).trim().slice(0, MAX_OUTPUT_CHARS),
      durationMs: finishedAtMs - startedAtMs,
    })
  }

  const outcome: EvalOutcome = results.some((r) => r.required && !r.passed) ? 'fail' : 'pass'
  const failed = results.filter((r) => !r.passed)
  const summary = summarize(results)
  const evaluatedAtMs = await host.now()

  return { outcome, checks: results, failed, summary, evaluatedAtMs }
}

export function summarize(checks: readonly EvalCheckResult[]): string {
  const total = checks.length
  const passed = checks.filter((c) => c.passed).length
  const base = `${passed}/${total} checks passed`
  const failedRequiredNames = checks.filter((c) => c.required && !c.passed).map((c) => c.name)
  if (failedRequiredNames.length === 0) return base
  return `${base}; failed: ${failedRequiredNames.join(', ')}`
}

