// hooks/blocker.ts — pure classifier: decides whether a failed attempt is
// worth retrying or needs a human, and maps that to a WorkflowEvent.

import type { EvalReport } from './eval'
import type { WorkflowEvent } from './state'

export type BlockerKind = 'retryable' | 'needs_human'

export type BlockerPattern = {
  id: string
  pattern: RegExp
  question: string
}

export type BlockerClassification = {
  kind: BlockerKind
  reason: string
  question?: string
  signals: readonly string[]
}

export type ClassifyArgs = {
  report: EvalReport
  attempt: number
  maxAttempts: number
  agentAnswer?: string
  spawnDenied?: string
}

export const BLOCKER_PATTERNS: readonly BlockerPattern[] = [
  {
    id: 'missing_credentials',
    pattern: /\b(API key|credential|token|secret)s? (missing|not set|required|not found)\b/i,
    question: 'Which credential/secret should be used, and where can the agent read it from?',
  },
  {
    id: 'ambiguous_requirement',
    pattern: /\b(ambiguous|unclear|not specified|which (one|approach)|please clarify)\b/i,
    question: 'The ticket is ambiguous — can you clarify the expected behavior?',
  },
  {
    id: 'permission_denied',
    pattern: /\b(permission denied|EACCES|not authorized|forbidden)\b/i,
    question: 'The agent hit a permissions error — can you grant access or a workaround?',
  },
  {
    id: 'external_dependency',
    pattern: /\b(external service|third[- ]party|network unreachable|DNS)\b/i,
    question: 'An external dependency is unavailable — how should the agent proceed?',
  },
]

export function classifyFailure(args: ClassifyArgs): BlockerClassification {
  if (args.spawnDenied !== undefined) {
    return {
      kind: 'needs_human',
      reason: `spawn denied: ${args.spawnDenied}`,
      question: 'A tool call was denied — how should the agent proceed?',
      signals: ['spawn_denied'],
    }
  }

  const text = [
    ...args.report.failed.map((check) => check.output),
    args.agentAnswer ?? '',
  ].join('\n')

  const signals: string[] = []
  for (const blocker of BLOCKER_PATTERNS) {
    if (blocker.pattern.test(text)) {
      signals.push(blocker.id)
    }
  }

  if (signals.length > 0) {
    const firstId = signals[0]
    const matched = BLOCKER_PATTERNS.find((blocker) => blocker.id === firstId)
    return {
      kind: 'needs_human',
      reason: `blocker signal: ${firstId} (attempt ${args.attempt}/${args.maxAttempts})`,
      question: matched?.question,
      signals,
    }
  }

  return {
    kind: 'retryable',
    reason: `${args.report.summary} (attempt ${args.attempt}/${args.maxAttempts})`,
    signals,
  }
}

export function toWorkflowEvent(
  classification: BlockerClassification,
  attempt: number,
  maxAttempts: number,
): WorkflowEvent {
  if (classification.kind === 'needs_human') return 'BLOCKER_FOUND'
  return attempt >= maxAttempts ? 'EXHAUSTED' : 'RETRY'
}

